# Where a Primer reporting-guide module fits a practice study, its findings replace the
# practice's normal report (the user's preference, 2026-11-12). Practice normals remain only
# where Primer has no module for the examination.
MODULE_FINDINGS = {
    'mri-iac': 'derived', 
    'ct-neck': ('derived', 'ra.mri-neck-spaces'), 'us-neck': ('derived', 'ra.cervical-lymph-nodes'),
    'fl-barium-swallow': 'derived', 'fl-contrast-swallow-leak': 'derived', 'xr-chest-immigration': 'derived',
    'cta-lower-limbs': 'derived', 'us-abdominal-wall': 'derived', 'mri-kidneys': 'derived',
    'mri-liver-pancreas': 'derived', 'mri-female-pelvis': ('teaching', 'ra.mri-endometriosis'),
    'us-pelvis': 'teaching', 'us-scrotum': 'teaching',
    
    'xr-wrist': 'derived', 'xr-scaphoid': 'derived', 'xr-standing-knees': 'derived', 'xr-sij': 'derived',
    'xr-cervical-spine': 'derived', 'ct-wrist-hand': 'derived',
    'mri-hip': 'derived', 'mri-thigh': ('teaching', 'ra.mri-muscle-injury'), 'mri-lower-leg': 'derived',
    
}

# Prism title variants the practice's library lacks, so the shared "MRI pelvis" can be told apart.
EXTRA_TITLES = {
    'mri-rectum': ['MRI pelvis (rectum)'],
    'mri-prostate': ['MRI pelvis (prostate)'],
    'mri-female-pelvis': ['MRI pelvis (female)'],
}

for _exam in EXAMS:
    _change = MODULE_FINDINGS.get(_exam['id'])
    if _change:
        _mode, _teaching = (_change, None) if isinstance(_change, str) else _change
        _exam['findings'] = _mode
        if _teaching:
            _exam['teaching'] = _teaching
    if _exam['id'] in EXTRA_TITLES:
        _exam['extra_titles'] = EXTRA_TITLES[_exam['id']]
_unknown = (set(MODULE_FINDINGS) | set(EXTRA_TITLES)) - {e['id'] for e in EXAMS}
assert not _unknown, _unknown
